<template>
  <section class="admin-container"><header class="admin-header"><div><p class="eyebrow">CONTROL ROOM / ADMIN</p><h1>Quản trị <em>LuNu.</em></h1><p>Quản lý kho nhạc Cloudinary, nội dung Supabase và quyền truy cập của thành viên.</p></div><div class="tab-buttons"><button :class="{ active: activeTab === 'songs' }" @click="activeTab = 'songs'">Kho nhạc <b>{{ songsList.length }}</b></button><button :class="{ active: activeTab === 'users' }" @click="activeTab = 'users'">Tài khoản <b>{{ usersList.length }}</b></button></div></header>
    <div v-if="errorMsg" class="admin-alert">{{ errorMsg }}</div>
    <div v-if="activeTab === 'songs'" class="admin-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">IMPORT PIPELINE</span><h2>Thêm nhạc từ YouTube</h2></div><span class="status-dot">● ONLINE</span></div><div class="bulk-lyrics-card"><div class="panel-heading"><div><span class="panel-kicker">LYRICS BATCH</span><h2>Nhập lyrics hàng loạt</h2></div><div class="panel-actions"><button type="button" class="refresh-btn" @click="downloadLyricsTemplate" :disabled="!songsList.length">Tải mẫu 188 bài</button><button type="button" class="primary-btn" @click="handleBulkLyricsImport" :disabled="isBulkLyricsSaving || !bulkLyricsText.trim()">{{ isBulkLyricsSaving ? 'Đang cập nhật...' : 'Cập nhật lyrics' }}</button></div></div><p class="edit-note">Dùng JSON mẫu, điền lyrics không timestamp rồi dán lại vào đây. Hệ thống chỉ cập nhật cột <code>lyrics</code>; URL audio Cloudinary, mã bài và metadata khác được giữ nguyên.</p><textarea v-model="bulkLyricsText" class="bulk-lyrics-textarea" rows="7" placeholder="{\n  &quot;items&quot;: [\n    { &quot;id&quot;: &quot;uuid-cua-bai&quot;, &quot;lyrics&quot;: &quot;Nội dung lời bài hát...&quot; }\n  ]\n}"></textarea></div><DiscordBotSearch @song-added="refreshSongs" /><div class="panel-heading list-heading"><div><span class="panel-kicker">LIBRARY INDEX</span><h2>Danh sách nhạc hệ thống</h2></div><div class="panel-actions"><button class="refresh-btn" @click="restoreLegacy">↥ Khôi phục 188 bài</button><button class="refresh-btn" @click="refreshSongs">↻ Làm mới</button></div></div><div v-if="songsLoading" class="inline-state">Đang tải thư viện...</div><div v-else-if="!songsList.length" class="inline-state">Chưa có bài hát nào trong kho.</div><div v-else class="list-wrapper"><div v-for="song in songsList" :key="song.id" class="list-item"><div class="info"><img :src="song.cover || '/images/ChoCiu.jpg'" :alt="song.title" class="tiny-cover" /><div><strong>{{ song.title }}</strong><span>{{ song.artist || 'Unknown artist' }}</span><small class="media-key">{{ song.media_key || 'LEGACY / 188 GỐC' }}</small></div></div><div class="row-actions"><button type="button" @click.stop="findLyrics(song)" class="lyrics-btn" :disabled="isLyricsSearching" title="Tìm lyrics từ nguồn được hỗ trợ">Tìm lời</button><button type="button" @click.stop="startEdit(song)" class="edit-btn" title="Chỉnh sửa metadata bài hát">Sửa</button><button type="button" @click="handleDeleteSong(song.id)" class="delete-btn">Xóa</button></div></div></div></div>
    <Teleport to="body"><div v-if="editingSong && activeTab === 'songs'" class="edit-modal-backdrop" @click.self="cancelEdit"><section class="edit-song-panel glass-panel" role="dialog" aria-modal="true" aria-labelledby="edit-song-title" @click.stop><div class="panel-heading"><div><span class="panel-kicker">METADATA EDITOR</span><h2 id="edit-song-title">Chỉnh sửa bài hát</h2></div><button class="refresh-btn" type="button" @click="cancelEdit">Đóng</button></div><p class="edit-note">Bạn có thể đổi tên, ca sĩ, ảnh bìa hoặc lyrics. Link audio Cloudinary và mã bài vẫn được giữ nguyên.</p><form class="edit-song-form" @submit.prevent="saveSong"><label><span>TÊN BÀI HÁT</span><input v-model.trim="editMetadata.title" required maxlength="240" /></label><label><span>CA SĨ / NGHỆ SĨ</span><input v-model.trim="editMetadata.artist" required maxlength="160" /></label><label class="wide"><span>LYRICS</span><textarea v-model="editMetadata.lyrics" rows="5" maxlength="100000"></textarea></label><div class="form-actions"><button type="button" class="refresh-btn" @click="cancelEdit">Hủy</button><button type="submit" class="primary-btn" :disabled="isSongSaving">{{ isSongSaving ? 'Đang lưu...' : 'Lưu metadata' }}</button></div></form></section></div></Teleport>
    <Teleport to="body"><div v-if="lyricsSearchSong && lyricsCandidates.length" class="lyrics-modal-backdrop" @click.self="closeLyricsPreview"><section class="lyrics-modal glass-panel" role="dialog" aria-modal="true" aria-labelledby="lyrics-modal-title" @click.stop><div class="panel-heading"><div><span class="panel-kicker">LYRICS REVIEW / LRCLIB</span><h2 id="lyrics-modal-title">Xem trước lời bài hát</h2><p class="lyrics-song-label">{{ lyricsSearchSong.title }} — {{ lyricsSearchSong.artist }}</p></div><button type="button" class="refresh-btn" @click="closeLyricsPreview">Đóng</button></div><p class="edit-note">Nguồn trả về có thể là bản plain lyrics hoặc đã được bỏ timestamp. Hãy kiểm tra nội dung và chọn đúng kết quả trước khi lưu.</p><div class="lyrics-candidates"><button v-for="candidate in lyricsCandidates" :key="candidate.provider_id || candidate.title" type="button" :class="['lyrics-candidate', { selected: selectedLyrics === candidate }]" @click="selectedLyrics = candidate"><strong>{{ candidate.title }}</strong><span>{{ candidate.artist }}<template v-if="candidate.album"> · {{ candidate.album }}</template></span></button></div><div v-if="selectedLyrics" class="lyrics-preview"><div class="lyrics-preview-meta"><span>{{ selectedLyrics.provider }}</span><a :href="selectedLyrics.source_url" target="_blank" rel="noreferrer">Mở nguồn</a></div><pre>{{ selectedLyrics.lyrics }}</pre></div><div class="form-actions"><button type="button" class="refresh-btn" @click="closeLyricsPreview">Hủy</button><button type="button" class="primary-btn" :disabled="isLyricsSaving || !selectedLyrics" @click="confirmLyrics">{{ isLyricsSaving ? 'Đang lưu...' : 'Xác nhận và lưu lyrics' }}</button></div></section></div></Teleport>
    <div v-if="activeTab !== 'songs'" class="admin-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">ACCESS MANAGEMENT</span><h2>Cấp tài khoản mới</h2></div></div><form @submit.prevent="handleAddUser" class="add-user-form"><label><span>TÊN ĐĂNG NHẬP</span><input v-model.trim="newUser.username" placeholder="member.name" required minlength="2" /></label><label><span>MẬT KHẨU</span><input v-model="newUser.password" type="password" placeholder="Tối thiểu 8 ký tự" required minlength="8" /></label><label><span>VAI TRÒ</span><select v-model="newUser.role"><option value="user">Member</option><option value="admin">Admin</option></select></label><button type="submit" class="primary-btn" :disabled="isSubmitting">{{ isSubmitting ? 'Đang lưu...' : 'Cấp quyền →' }}</button></form><p v-if="userMsg" class="success-msg">{{ userMsg }}</p><div class="panel-heading list-heading"><div><span class="panel-kicker">MEMBERS DIRECTORY</span><h2>Danh sách tài khoản</h2></div><button class="refresh-btn" @click="refreshUsers">↻ Làm mới</button></div><div class="list-wrapper"><div v-for="user in usersList" :key="user.id" class="list-item"><div class="user-row"><div class="avatar">{{ user.username.slice(0,1).toUpperCase() }}</div><div><strong>{{ user.username }}</strong><span>{{ user.role === 'admin' ? 'Administrator' : 'Member' }}</span></div></div><button v-if="user.username !== 'admin'" @click="handleDeleteUser(user.id)" class="delete-btn">Thu hồi</button></div></div></div>
  </section>
</template>

<script setup>
import { onMounted, ref } from 'vue';
import DiscordBotSearch from '../components/DiscordBotSearch.vue';
import { getUsers, addUser, deleteUser, getSongs, deleteSong, updateSong, searchSongLyrics, updateSongLyricsBulk, importLegacySongs } from '../services/api';
import { loadSongs } from '../data/songs';

const activeTab = ref('songs');
const songsList = ref([]); const usersList = ref([]); const userMsg = ref(''); const errorMsg = ref(''); const isSubmitting = ref(false); const songsLoading = ref(false);
const newUser = ref({ username: '', password: '', role: 'user' }); const editingSong = ref(null); const editMetadata = ref({ title: '', artist: '', cover: '', lyrics: '' }); const isSongSaving = ref(false); const bulkLyricsText = ref(''); const isBulkLyricsSaving = ref(false); const lyricsSearchSong = ref(null); const lyricsCandidates = ref([]); const selectedLyrics = ref(null); const isLyricsSearching = ref(false); const isLyricsSaving = ref(false);
const restoreLegacy = async () => { if (!window.confirm('Khôi phục toàn bộ 188 bài hát vào Supabase? Các URL đã tồn tại sẽ được bỏ qua.')) return; songsLoading.value = true; errorMsg.value = ''; try { const response = await importLegacySongs(); userMsg.value = response.message; await refreshSongs(); window.setTimeout(() => { userMsg.value = ''; }, 5000); } catch (error) { errorMsg.value = error.message; } finally { songsLoading.value = false; } };
const refreshSongs = async () => { songsLoading.value = true; errorMsg.value = ''; try { songsList.value = await getSongs(); await loadSongs(); } catch (error) { errorMsg.value = error.message; } finally { songsLoading.value = false; } };
const refreshUsers = async () => { errorMsg.value = ''; try { usersList.value = await getUsers(); } catch (error) { errorMsg.value = error.message; } };
const startEdit = (song) => { editingSong.value = song; editMetadata.value = { title: song.title || '', artist: song.artist || '', cover: song.cover || '', lyrics: song.lyrics || '' }; }; const cancelEdit = () => { editingSong.value = null; }; const saveSong = async () => { if (!editingSong.value) return; isSongSaving.value = true; errorMsg.value = ''; try { const response = await updateSong(editingSong.value.id, editMetadata.value); userMsg.value = response.message || 'Đã cập nhật metadata bài hát.'; cancelEdit(); await refreshSongs(); } catch (error) { errorMsg.value = error.message; } finally { isSongSaving.value = false; } };
const downloadLyricsTemplate = () => { const items = songsList.value.map((song) => ({ id: song.id, title: song.title, artist: song.artist || '', lyrics: '' })); const blob = new Blob([JSON.stringify({ items }, null, 2)], { type: 'application/json;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'lunu-188-lyrics-template.json'; link.click(); URL.revokeObjectURL(url); };
const handleBulkLyricsImport = async () => { errorMsg.value = ''; userMsg.value = ''; let parsed; try { parsed = JSON.parse(bulkLyricsText.value); } catch { errorMsg.value = 'JSON không hợp lệ. Hãy dùng file mẫu rồi chỉ điền nội dung vào trường lyrics.'; return; } const items = Array.isArray(parsed) ? parsed : parsed?.items; if (!Array.isArray(items) || !items.length) { errorMsg.value = 'JSON phải có dạng {"items":[{"id":"...","lyrics":"..."}]}.'; return; } const normalized = items.filter((item) => item && String(item.id || '').trim() && String(item.lyrics || '').trim()).map((item) => ({ id: String(item.id).trim(), lyrics: String(item.lyrics).trim() })); if (!normalized.length) { errorMsg.value = 'Chưa có mục lyrics nào có nội dung để cập nhật.'; return; } if (!window.confirm(`Cập nhật lyrics cho ${normalized.length} bài hát? URL Cloudinary sẽ không bị thay đổi.`)) return; isBulkLyricsSaving.value = true; try { const response = await updateSongLyricsBulk(normalized); userMsg.value = response.message; bulkLyricsText.value = ''; await refreshSongs(); if (response.failed_count) errorMsg.value = response.failed.map((item) => `${item.id}: ${item.message}`).join(' | '); } catch (error) { errorMsg.value = error.message; } finally { isBulkLyricsSaving.value = false; } };
const findLyrics = async (song) => { lyricsSearchSong.value = song; lyricsCandidates.value = []; selectedLyrics.value = null; isLyricsSearching.value = true; errorMsg.value = ''; try { const response = await searchSongLyrics(song.id); lyricsCandidates.value = response.results || []; selectedLyrics.value = lyricsCandidates.value[0] || null; if (!lyricsCandidates.value.length) errorMsg.value = response.message || 'Không tìm thấy lyrics phù hợp.'; } catch (error) { lyricsSearchSong.value = null; errorMsg.value = error.message; } finally { isLyricsSearching.value = false; } };
const closeLyricsPreview = () => { lyricsSearchSong.value = null; lyricsCandidates.value = []; selectedLyrics.value = null; };
const confirmLyrics = async () => { if (!lyricsSearchSong.value || !selectedLyrics.value) return; isLyricsSaving.value = true; errorMsg.value = ''; try { const response = await updateSongLyricsBulk([{ id: lyricsSearchSong.value.id, lyrics: selectedLyrics.value.lyrics }]); if (response.failed_count) throw new Error(response.failed?.[0]?.message || 'Không thể lưu lyrics.'); userMsg.value = `Đã lưu lyrics cho “${lyricsSearchSong.value.title}”.`; closeLyricsPreview(); await refreshSongs(); } catch (error) { errorMsg.value = error.message; } finally { isLyricsSaving.value = false; } };
const handleDeleteSong = async (id) => { if (!window.confirm('Xóa bài hát này khỏi thư viện?')) return; try { await deleteSong(id); await refreshSongs(); } catch (error) { errorMsg.value = error.message; } };
const handleAddUser = async () => { isSubmitting.value = true; errorMsg.value = ''; try { const response = await addUser(newUser.value.username, newUser.value.password, newUser.value.role); if (!response.success) throw new Error(response.message); userMsg.value = response.message; newUser.value = { username: '', password: '', role: 'user' }; await refreshUsers(); window.setTimeout(() => { userMsg.value = ''; }, 3000); } catch (error) { errorMsg.value = error.message; } finally { isSubmitting.value = false; } };
const handleDeleteUser = async (id) => { if (!window.confirm('Thu hồi tài khoản này?')) return; try { await deleteUser(id); await refreshUsers(); } catch (error) { errorMsg.value = error.message; } };
onMounted(() => { refreshSongs(); refreshUsers(); });
</script>

<style scoped>
