nsparent; color:var(--mint); cursor:pointer; font-size:10px; }.lyrics-btn:hover { background:rgba(139,224,190,.1); }.lyrics-btn:disabled { opacity:.55; cursor:progress; }.edit-btn { border:1px solid rgba(245,185,122,.25); border-radius:8px; padding:7px 9px; background:transparent; color:var(--gold); cursor:pointer; font-size:10px; }.edit-btn:hover { background:rgba(245,185,122,.1); }.lyrics-modal-backdrop { position:fixed; inset:0; z-index:1001; display:grid; place-items:center; padding:20px; background:rgba(3,5,9,.82); backdrop-filter:blur(12px); }.lyrics-modal { width:min(820px,100%); max-height:min(840px,calc(100vh - 40px)); overflow:auto; padding:clamp(18px,3vw,28px); border:1px solid rgba(139,224,190,.28); border-radius:18px; box-shadow:0 24px 80px rgba(0,0,0,.5); }.lyrics-song-label { margin-top:6px; color:var(--text-sub); font-size:10px; }.lyrics-candidates { display:flex; gap:7px; overflow:auto; padding-bottom:10px; }.lyrics-candidate { min-width:180px; display:flex; flex-direction:column; align-items:flex-start; gap:5px; padding:11px; border:1px solid var(--hairline); border-radius:10px; background:rgba(255,255,255,.025); color:var(--text-main); cursor:pointer; text-align:left; }.lyrics-candidate span { color:var(--text-sub); font-size:9px; }.lyrics-candidate.selected { border-color:var(--mint); background:rgba(139,224,190,.1); }.lyrics-preview { margin:8px 0 16px; border:1px solid var(--hairline-soft); border-radius:11px; background:rgba(3,5,9,.4); }.lyrics-preview-meta { display:flex; justify-content:space-between; padding:10px 12px; border-bottom:1px solid var(--hairline-soft); color:var(--mint); font:9px var(--font-mono); }.lyrics-preview-meta a { color:var(--gold); }.lyrics-preview pre { max-height:360px; overflow:auto; margin:0; padding:15px; color:var(--text-main); white-space:pre-wrap; font:11px/1.65 var(--font-body); }.edit-modal-backdrop { position:fixed; inset:0; z-index:1000; display:grid; place-items:center; padding:20px; background:rgba(3,5,9,.78); backdrop-filter:blur(12px); }.edit-song-panel { width:min(680px,100%); max-height:min(820px,calc(100vh - 40px)); overflow:auto; padding:clamp(18px,3vw,28px); border:1px solid var(--hairline); border-radius:18px; box-shadow:0 24px 80px rgba(0,0,0,.45); }.edit-note { margin:-7px 0 16px; color:var(--text-sub); font-size:10px; }.edit-song-form { display:grid; grid-template-columns:1fr 1fr; gap:10px; }.edit-song-form label { display:grid; gap:7px; }.edit-song-form label span { color:var(--text-faint); font:8px var(--font-mono); letter-spacing:1px; }.edit-song-form input,.edit-song-form textarea { width:100%; box-sizing:border-box; padding:11px 12px; border:1px solid var(--hairline); border-radius:9px; outline:0; background:rgba(3,5,9,.35); color:var(--text-main); font-size:11px; }.edit-song-form .wide,.edit-song-form .form-actions { grid-column:1/-1; }.edit-song-form .form-actions { display:flex; justify-content:flex-end; gap:8px; }.delete-btn { border: 1px solid rgba(255,109,125,.22); border-radius: 8px; padding: 7px 9px; background: transparent; color: var(--crimson); cursor: pointer; font-size: 10px; }.delete-btn:hover { background: rgba(255,109,125,.1); }.inline-state { padding: 30px; color: var(--text-sub); text-align: center; font-size: 11px; }.add-user-form { display: grid; grid-template-columns: 1.1fr 1.1fr .7fr auto; align-items: end; gap: 10px; }.add-user-form label { display: grid; gap: 7px; }.add-user-form label span { color: var(--text-faint); font: 8px var(--font-mono); letter-spacing: 1px; }.add-user-form input, .add-user-form select { min-width: 0; padding: 11px 12px; border: 1px solid var(--hairline); border-radius: 9px; outline: 0; background: rgba(3,5,9,.35); color: var(--text-main); font-size: 11px; }.add-user-form input:focus { border-color: var(--gold); }.primary-btn { border: 0; border-radius: 9px; padding: 11px 13px; background: var(--gold); color: #171218; cursor: pointer; font-size: 10px; font-weight: 800; white-space: nowrap; }.primary-btn:disabled { opacity: .5; cursor: progress; }.success-msg { margin-top: 12px; color: var(--mint); font-size: 10px; }@media (max-width: 760px) { .lyrics-modal-backdrop { padding:10px; align-items:end; }.lyrics-modal { max-height:calc(100vh - 20px); border-radius:16px 16px 0 0; }.lyrics-candidates { flex-direction:column; }.lyrics-candidate { width:100%; box-sizing:border-box; }.edit-modal-backdrop { padding:10px; align-items:end; }.edit-song-panel { max-height:calc(100vh - 20px); border-radius:16px 16px 0 0; }.edit-song-form { grid-template-columns:1fr; }.edit-song-form .wide,.edit-song-form .form-actions { grid-column:auto; }.admin-header { align-items: flex-start; flex-direction: column; }.tab-buttons { align-self: stretch; }.tab-buttons button { flex: 1; }.add-user-form { grid-template-columns: 1fr; }.admin-container { padding-bottom: 95px; } }
</style>
